contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address user, uint depositAmount, uint minDeposit) public payable {
        require(minDeposit > 0);
        // Set MinDeposit to our parameter so we can test boundary conditions
        // Note: MinDeposit is a public state variable, but we cannot set it directly.
        // We'll work with the existing MinDeposit and use depositAmount accordingly.

        // Record balance before deposit
        uint balanceBefore = c.balances(user);

        // Fund this contract if needed
        require(address(this).balance >= depositAmount);

        bool reverted;
        try c.Deposit{value: depositAmount}() { reverted = false; } catch { reverted = true; }

        uint balanceAfter = c.balances(user);

        // If deposit succeeded (amount >= MinDeposit and no revert),
        // the balance must not have decreased.
        // If it reverted (amount < MinDeposit or other failure), no condition on balance change.
        assert(!reverted || depositAmount < c.MinDeposit() ? true : balanceAfter >= balanceBefore);
    }
    receive() external payable {}
}

