pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 cashoutAmt) public {
        // Restrict depositor to non-zero address to avoid precompile collisions
        vm.assume(depositor != address(0));
        // Bound deposit to [MinDeposit, type(uint256).max/2] to avoid overflow in reference (safe for this property)
        uint256 minDep = c.MinDeposit();
        vm.assume(depositAmt >= minDep && depositAmt <= type(uint256).max / 2);
        // Bound cashout to [0, depositAmt * 2] to allow testing both valid and invalid cashouts, but we restrict to <= depositAmt for valid case (the invariant only concerns successful cashouts)
        // We let the fuzzer choose any cashout; the invariant only applies after successful cashout
        vm.assume(cashoutAmt <= type(uint256).max / 2);

        // Fund depositor
        vm.deal(depositor, depositAmt * 2);
        // Deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Record initial balance
        uint256 balanceBefore = c.balances(depositor);

        // If cashout is <= current balance, perform cashout; otherwise skip (invariant only holds after successful cashout)
        if (cashoutAmt <= balanceBefore) {
            vm.prank(depositor);
            c.CashOut(cashoutAmt);
            // After successful cashout, final balance should equal initial balance - cashoutAmt
            // Since we only performed one deposit, balanceBefore should equal depositAmt in the reference.
            // However, the buggy version subtracts on deposit, so balanceBefore = depositAmt - depositAmt = 0, which means cashout will fail or balance goes negative.
            // To make this a general rule: after a successful cashout, the final balance must be exactly balanceBefore - cashoutAmt,
            // because the only modification to balance since the deposit was the cashout.
            // In the reference, this holds. In the buggy version, if deposit subtracted, balanceBefore = 0, so cashout might revert
            // or result in underflow, but if cashoutAmt=0, it succeeds; still, the invariant must be the arithmetical relation.
            uint256 finalBalance = c.balances(depositor);
            assertTrue(finalBalance == balanceBefore - cashoutAmt);
        } else {
            // If cashout would exceed balance, the call should revert. We can assert that the state remains unchanged.
            uint256 balBeforeAttempt = c.balances(depositor);
            try c.CashOut(cashoutAmt) {
                // If it didn't revert, final balance must still follow the rule? No, the spec says it should revert, but the reference reverts due to require? Actually, the reference's CashOut has if(_am<=balances[msg.sender]) else it does nothing (no revert).
                // So the state is unchanged. We assert that balance remains same.
                uint256 balAfter = c.balances(depositor);
                assertTrue(balAfter == balBeforeAttempt);
            } catch {
                // If it reverts, state unchanged.
                uint256 balAfter = c.balances(depositor);
                assertTrue(balAfter == balBeforeAttempt);
            }
        }
    }
}

