pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, uint256 cashAmt, address actor) public {
        // Restrict to admissible domain: deposits must be at least MinDeposit, cashout <= initial balance
        uint256 minDep = c.MinDeposit();
        vm.assume(deposit1 >= minDep && deposit2 >= minDep);
        vm.assume(deposit1 <= type(uint256).max - deposit2);
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(cashAmt <= deposit1 + deposit2);

        // Fund and deposit
        vm.deal(actor, deposit1 + deposit2);
        vm.prank(actor);
        c.Deposit{value: deposit1}();
        vm.prank(actor);
        c.Deposit{value: deposit2}();

        uint256 balBefore = c.balances(actor);

        // Cash out an amount not exceeding balance
        vm.prank(actor);
        bool cashOk = true;
        try c.CashOut(cashAmt) { cashOk = true; } catch { cashOk = false; }

        if (!cashOk) return; // if cashout reverts, trivially fine

        uint256 balAfter = c.balances(actor);
        uint256 expectedMin = balBefore - cashAmt;
        assertTrue(balAfter >= expectedMin);
    }
}

