contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashoutAmount, uint256 otherKey) public {
        vm.assume(depositAmount >= c.MinDeposit());
        vm.assume(depositAmount <= type(uint128).max);
        address alice = address(0x1);
        vm.deal(alice, depositAmount);
        vm.prank(alice);
        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(alice);
        vm.assume(cashoutAmount <= balBefore);

        try c.CashOut(cashoutAmount) {
            uint256 sumBalances = c.balances(alice) + c.balances(address(uint160(otherKey)));
            assertTrue(sumBalances >= address(c).balance);
        } catch {
            // if CashOut reverts, invariant vacuously holds for this attempt
        }
    }
}

