pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(
        uint256 depositAmount,
        uint256 cashOutAmount,
        address depositor
    ) public {
        // Bound deposit to the admissible domain: at least MinDeposit and within realistic limits
        uint256 minD = c.MinDeposit();
        depositAmount = bound(depositAmount, minD, 1000 ether);
        cashOutAmount = bound(cashOutAmount, 0, 1000 ether);

        // depositor must be a normal EOA, not address(0) or the test contract itself
        vm.assume(depositor != address(0) && depositor != address(this) && depositor != address(c));

        // Fund the depositor
        vm.deal(depositor, 2000 ether);

        // 1) Depositor makes a deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmount}();

        // 2) Depositor executes a cashout (amount may be 0 or up to their balance)
        uint256 preCashOutContractBalance = address(c).balance;
        uint256 preCashOutTotalBalances = c.balances(depositor); // only one actor matters for the invariant

        vm.prank(depositor);
        try c.CashOut(cashOutAmount) {} catch {}

        uint256 postCashOutContractBalance = address(c).balance;
        uint256 postCashOutTotalBalances = c.balances(depositor);

        // Invariant: total recorded balance must never be strictly less than contract balance,
        // because contract holds ether for all depositors.
        // With the bug, a deposit decreases balances but gives ether to the contract,
        // so a cashout can drain ether and make total balances < contract balance.
        assertTrue(postCashOutTotalBalances >= postCashOutContractBalance);
    }
}
